    privacyPolicy9:
      'Plus/Pro-abonnementen worden via Stripe gefactureerd. Planwijzigingen (bijv. van Plus naar Pro) zijn pas mogelijk na afloop van je huidige betaalde periode, nadat automatische verlenging is geannuleerd.',
    privacyPolicy10:
      'Bereikmeting: Google Analytics en Vercel Analytics. Een banner kan om toestemming vragen. Google AdSense zit in de code maar de ads-UI is gepauzeerd. Details: volledig beleid.',
