      'ScanPlay is bedoeld voor personen van minstens 13 jaar. Bij registratie kun je dat verklaren via een vakje: het is geen identiteitscontrole, en er wordt geen ouderlijke toestemming verzameld. Als een account van iemand onder de 13 is, mail support@scanplay.org.',
