    privacyPolicy1: 'ScanPlay (scanplay.org) está editado por El Fahmi, Ikram (Bélgica, n.º 1037.806.166). Contacto: support@scanplay.org.',
    privacyPolicy2: 'Datos de cuenta: email, acceso opcional con Google, nombre, avatar, progreso (XP, racha, mazos, errores, logros, monedero), suscripción y preferencias.',
    privacyPolicy3: 'Sincronización en la nube vía Supabase al iniciar sesión. Perfil visible para amigos: nombre, avatar, stats y logros. Los mensajes del coach pueden guardarse.',
    privacyPolicy4: 'Sin cuenta, el escaneo se lee en el navegador. Con sesión, la imagen puede enviarse a OpenAI el tiempo de extraer tarjetas; ScanPlay no guarda el archivo original. El texto de las tarjetas y una miniatura pueden quedar. La pronunciación puede enviar audio corto a Groq.',
