    privacySection: "الخصوصية",
    privacyIntro: "كيف يستخدم ScanPlay بياناتك ويحميها.",
    privacyDeleteHint: "يمكنك حذف حسابك من هذه الشاشة. عليك كتابة OK ثم الضغط على متابعة. عندها يمحو ScanPlay حسابك في Supabase والبيانات المرتبطة به. قد يحتفظ مزوّدون آخرون (الدفع، قياس الجمهور، الذكاء الاصطناعي) بآثار وفق قواعدهم الخاصة.",
    privacyOpen: "قراءة سياسة الخصوصية",
