    privacyClose: "إغلاق",
    privacyFullPolicy: "قراءة النسخة الكاملة",
    termsOpen: "شروط الاستخدام",
    privacyPolicy1: "ScanPlay (scanplay.org) من إصدار El Fahmi, Ikram (بلجيكا، رقم 1037.806.166). للتواصل: support@scanplay.org.",
    privacyPolicy2: "بيانات الحساب: البريد الإلكتروني، وتسجيل الدخول بـ Google إن وُجد، والاسم المستعار، والصورة الرمزية، والتقدّم (XP، السلسلة، الأوراق، الأخطاء، الإنجازات، المحفظة)، والاشتراك والتفضيلات (اللغة، المظهر، الأصوات).",
    privacyPolicy3: "مزامنة سحابية عبر Supabase عندما تكون مسجَّلاً. الملف الذي يراه أصدقاؤك: الاسم المستعار والصورة الرمزية والإحصاءات والإنجازات المفتوحة. قد تُحفظ رسائل المدرّب والاستخدام المرتبط بها.",
    privacyPolicy4: "بدون حساب، تُقرأ الصورة الممسوحة داخل المتصفح. وعند تسجيل الدخول، قد تُرسَل الصورة إلى OpenAI خلال مدة استخراج البطاقات فقط؛ ولا يحتفظ ScanPlay بالملف الأصلي. وقد يبقى نص البطاقات وصورة مصغّرة. وقد يرسل النطق مقطعاً صوتياً قصيراً إلى Groq.",
    privacyPolicy5: "اللعب الجماعي: رمز الغرفة والنتائج والحضور في الغرفة. تبقى البيانات في قاعدة البيانات مدة عمل الميزة.",
    privacyPolicy6: "لا يبيع ScanPlay بياناتك. يمكنك حذف حسابك من الإعدادات (التأكيد بكتابة OK ثم متابعة). يمحو التطبيق عندها حسابك في Supabase وبيانات ScanPlay الخاصة بك (الأوراق، الإحصاءات، المدرّب، العلاقات) وكذلك النسخ المحلية المرتبطة. يمكنك أيضاً طلب الاطلاع على بياناتك عبر support@scanplay.org.",
    privacyAboutHeading: "نبذة",
    privacyPolicy7: "ScanPlay مشروع مستقل أنشأه Bilal El Fahmi. الهدف: جعل المراجعة أبسط وأكثر تحفيزاً بفضل اللعب، دون أن يحلّ محلّ درسك.",
    privacyPolicy8: "تطبيق ويب تقدّمي (PWA) متاح على scanplay.org. لأي سؤال أو اقتراح أو ملاحظة: support@scanplay.org.",
    privacyPolicy9: "اشتراكات Plus/Pro: الدفع عبر Stripe. لا يمكن تغيير الباقة (مثلاً من Plus إلى Pro) إلا عند انتهاء الفترة المدفوعة الحالية، بعد إلغاء التجديد التلقائي. تظهر تواريخ الانتهاء والتجديد في ملفك الشخصي.",
    privacyPolicy10: "قياس الجمهور: Google Analytics وVercel Analytics. قد يطلب منك شريط موافقتك. إعلانات Google AdSense مُدرجة في الشيفرة لكن عرضها متوقف حالياً. التفاصيل: السياسة الكاملة.",
    privacyPolicyMinors: "ScanPlay موجّه لمن بلغ 13 عاماً على الأقل. عند التسجيل، توجد خانة للتصريح بذلك: هذا ليس تحققاً من الهوية، ولا يُجمع أي موافقة من الوالدين. إذا كان حساب يخصّ طفلاً دون 13 عاماً، تواصل مع support@scanplay.org.",
